 useEffect(()=>{let active=true;async function start(){try{const L=await loadLeaflet();if(!active||!ref.current)return;const latest=coordinatesRef.current;const m=L.map(ref.current,{scrollWheelZoom:false,minZoom:2,maxZoom:18}).setView([latest.lat,latest.lng],13);mapRef.current=m;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors',maxZoom:18}).addTo(m);markerRef.current=L.marker([latest.lat,latest.lng],{icon:L.divIcon({className:'host-map-pin',html:'<span></span>',iconSize:[28,36],iconAnchor:[14,34]})}).addTo(m);m.on('click',(e:any)=>{const next=e.latlng;if(next.lat>=-90&&next.lat<=90&&next.lng>=-180&&next.lng<=180)callbackRef.current(next.lat,next.lng)});requestAnimationFrame(()=>{if(active)m.invalidateSize()})}catch{if(active)setFailed(true)}}start();return()=>{active=false;mapRef.current?.remove();mapRef.current=null;markerRef.current=null}},[]);
